//! The chat store: the identity, the row types, and the CRUD the
//! assistant's thread list and the relay's turn recorder drive over
//! [`AiStore`]. One row is one thread; its message rows carry the rendered
//! parts and the run metadata. The store's rows are the one source of
//! truth for the visible log: the panel paints what they hold, never the
//! runtime's own session files.

use crate::store::AiStore;
use crate::AiStoreError;

/// The identity of one assistant chat thread. Generated by the caller as
/// a v4 UUID (the [`SnippetId`](crate::SnippetId) spelling) so a thread
/// exists as data before it is stored. Serialises as its bare string so
/// it crosses process boundaries without a wrapper object.
#[derive(Debug, Clone, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
pub struct ChatId(String);

impl ChatId {
    /// Wraps an existing id string.
    pub fn new(value: String) -> Self {
        Self(value)
    }

    /// Generates a fresh chat id (a v4 UUID).
    pub fn generate() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// The id string.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for ChatId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

/// One side of a chat message. The row keeps the word as text (the
/// vocabulary is the recorder's, the knowledge table's own convention).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChatRole {
    /// The user's prompt.
    User,
    /// The assistant's answer.
    Assistant,
}

impl ChatRole {
    /// The store's word for the side.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::User => "user",
            Self::Assistant => "assistant",
        }
    }
}

/// One chat to insert: every column the caller owns; the store stamps
/// `created_at` and the first `last_touched_at` itself.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NewChat {
    /// The chat's identity.
    pub id: ChatId,
    /// The chat's title, the thread list's label.
    pub title: String,
}

/// One chat as the store reads it back: every column of the `chats`
/// table. Serialisable so the desktop host can carry rows across the IPC
/// boundary.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct ChatRow {
    /// The chat's identity.
    pub id: ChatId,
    /// The chat's title.
    pub title: String,
    /// The store's creation stamp (unix seconds).
    pub created_at: i64,
    /// The store's touch stamp (unix seconds), fresh on every message the
    /// chat gains; the thread list's recency ordering rides it.
    pub last_touched_at: i64,
}

/// One message row as the store reads it back: the rendered parts of one
/// side of a turn and, on the assistant's side, the run metadata. The
/// parts are the recorder's JSON array (text runs, completed tool calls,
/// notes) and travel whole; the store never interprets them.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ChatMessageRow {
    /// The row's identity, ascending with the conversation's order.
    pub id: i64,
    /// The chat the message belongs to.
    pub chat_id: ChatId,
    /// The side of the turn: `user` or `assistant`.
    pub role: String,
    /// The rendered parts, as the turn recorder folded them.
    pub parts: serde_json::Value,
    /// The run metadata (model, tier, finish reason, tool-call count,
    /// correlation id) on the assistant's side; absent on the user's.
    pub metadata: Option<serde_json::Value>,
    /// The store's creation stamp (unix seconds).
    pub created_at: i64,
}

impl AiStore {
    /// Inserts one chat and answers the row as it landed, the store's
    /// stamps included. The caller mints ids, so a collision is a caller
    /// bug, not a store state to paper over.
    ///
    /// # Errors
    /// Fails when the insert cannot run.
    pub fn insert_chat(&self, chat: &NewChat) -> Result<ChatRow, AiStoreError> {
        let conn = self.lock();
        conn.query_row(
            "INSERT INTO chats (id, title, created_at, last_touched_at)
             VALUES (?1, ?2, strftime('%s','now'), strftime('%s','now'))
             RETURNING id, title, created_at, last_touched_at",
            rusqlite::params![chat.id.as_str(), chat.title],
            chat_row,
        )
        .map_err(AiStoreError::Sqlite)
    }

    /// Inserts one message row and touches its chat, so the thread the
    /// turn lands in surfaces first in the list. The parts and metadata
    /// serialise to JSON text here; the caller hands the values.
    ///
    /// # Errors
    /// Fails when either statement cannot run.
    pub fn insert_chat_message(
        &self,
        chat: &ChatId,
        role: ChatRole,
        parts: &serde_json::Value,
        metadata: Option<&serde_json::Value>,
    ) -> Result<ChatMessageRow, AiStoreError> {
        let conn = self.lock();
        let parts = serde_json::to_string(parts).map_err(|source| {
            AiStoreError::Sqlite(rusqlite::Error::ToSqlConversionFailure(Box::new(source)))
        })?;
        let metadata = metadata
            .map(serde_json::to_string)
            .transpose()
            .map_err(|source| {
                AiStoreError::Sqlite(rusqlite::Error::ToSqlConversionFailure(Box::new(source)))
            })?;
        let row = conn
            .query_row(
                "INSERT INTO chat_messages (
                     chat_id, role, parts, metadata, created_at
                 ) VALUES (
                     ?1, ?2, ?3, ?4, strftime('%s','now')
                 )
                 RETURNING id, chat_id, role, parts, metadata, created_at",
                rusqlite::params![chat.as_str(), role.as_str(), parts, metadata],
                message_row,
            )
            .map_err(AiStoreError::Sqlite)?;
        conn.execute(
            "UPDATE chats SET last_touched_at = strftime('%s','now') WHERE id = ?1",
            rusqlite::params![chat.as_str()],
        )
        .map_err(AiStoreError::Sqlite)?;
        Ok(row)
    }

    /// Whether a chat with the id stands: the prompt path's guard, so a
    /// stale id from the UI never records orphan message rows against a
    /// chat that is not there.
    ///
    /// # Errors
    /// Fails when the query cannot run.
    pub fn chat_exists(&self, chat: &ChatId) -> Result<bool, AiStoreError> {
        let conn = self.lock();
        conn.query_row(
            "SELECT 1 FROM chats WHERE id = ?1",
            rusqlite::params![chat.as_str()],
            |row| {
                let one: i64 = row.get(0)?;
                Ok(one)
            },
        )
        .map(|_| true)
        .or_else(|e| match e {
            rusqlite::Error::QueryReturnedNoRows => Ok(false),
            other => Err(AiStoreError::Sqlite(other)),
        })
    }

    /// Every chat, the most recently touched first (the touch stamp, then
    /// id, so same-second rows still order deterministically): the read
    /// the panel's thread list paints from.
    ///
    /// # Errors
    /// Fails when the query cannot run.
    pub fn list_chats(&self) -> Result<Vec<ChatRow>, AiStoreError> {
        let conn = self.lock();
        let mut statement = conn
            .prepare(
                "SELECT id, title, created_at, last_touched_at
                 FROM chats
                 ORDER BY last_touched_at DESC, id DESC",
            )
            .map_err(AiStoreError::Sqlite)?;
        let rows = statement
            .query_map([], chat_row)
            .map_err(AiStoreError::Sqlite)?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(AiStoreError::Sqlite)
    }

    /// One chat's messages, oldest first: the rows the panel paints a
    /// loaded thread from. An unknown chat answers empty, the state of a
    /// thread with no turns.
    ///
    /// # Errors
    /// Fails when the query cannot run.
    pub fn chat_messages(&self, chat: &ChatId) -> Result<Vec<ChatMessageRow>, AiStoreError> {
        let conn = self.lock();
        let mut statement = conn
            .prepare(
                "SELECT id, chat_id, role, parts, metadata, created_at
                 FROM chat_messages
                 WHERE chat_id = ?1
                 ORDER BY id ASC",
            )
            .map_err(AiStoreError::Sqlite)?;
        let rows = statement
            .query_map(rusqlite::params![chat.as_str()], message_row)
            .map_err(AiStoreError::Sqlite)?;
        rows.collect::<Result<Vec<_>, _>>()
            .map_err(AiStoreError::Sqlite)
    }

    /// Rewrites one chat's title. Returns whether any row changed:
    /// `false` names an id no chat carries, for the caller to report.
    ///
    /// # Errors
    /// Fails when the update cannot run.
    pub fn rename_chat(&self, chat: &ChatId, title: &str) -> Result<bool, AiStoreError> {
        let conn = self.lock();
        conn.execute(
            "UPDATE chats SET title = ?2 WHERE id = ?1",
            rusqlite::params![chat.as_str(), title],
        )
        .map(|changed| changed > 0)
        .map_err(AiStoreError::Sqlite)
    }

    /// Deletes one chat together with its messages: a thread the user
    /// removed leaves nothing behind. Returns whether any chat row went.
    ///
    /// # Errors
    /// Fails when either statement cannot run.
    pub fn delete_chat(&self, chat: &ChatId) -> Result<bool, AiStoreError> {
        let conn = self.lock();
        conn.execute(
            "DELETE FROM chat_messages WHERE chat_id = ?1",
            rusqlite::params![chat.as_str()],
        )
        .map_err(AiStoreError::Sqlite)?;
        conn.execute(
            "DELETE FROM chats WHERE id = ?1",
            rusqlite::params![chat.as_str()],
        )
        .map(|changed| changed > 0)
        .map_err(AiStoreError::Sqlite)
    }
}

/// Reads one chat row from a query's cursor position.
fn chat_row(row: &rusqlite::Row<'_>) -> rusqlite::Result<ChatRow> {
    Ok(ChatRow {
        id: ChatId::new(row.get(0)?),
        title: row.get(1)?,
        created_at: row.get(2)?,
        last_touched_at: row.get(3)?,
    })
}

/// Reads one message row from a query's cursor position. The parts and
/// metadata read back as parsed JSON; a row the recorder wrote always
/// parses.
fn message_row(row: &rusqlite::Row<'_>) -> rusqlite::Result<ChatMessageRow> {
    let parts: String = row.get(3)?;
    let metadata: Option<String> = row.get(4)?;
    Ok(ChatMessageRow {
        id: row.get(0)?,
        chat_id: ChatId::new(row.get(1)?),
        role: row.get(2)?,
        parts: serde_json::from_str(&parts).map_err(|e| {
            rusqlite::Error::FromSqlConversionFailure(3, rusqlite::types::Type::Text, Box::new(e))
        })?,
        metadata: metadata
            .map(|text| {
                serde_json::from_str(&text).map_err(|e| {
                    rusqlite::Error::FromSqlConversionFailure(
                        4,
                        rusqlite::types::Type::Text,
                        Box::new(e),
                    )
                })
            })
            .transpose()?,
        created_at: row.get(5)?,
    })
}
